SELECT jsonb_build_object('events',(SELECT jsonb_agg(to_jsonb(e)) FROM (SELECT e.id_evento,e.nome_evento,e.data_inicial::date,e.data_final::date,e.ativo,(SELECT coalesce(jsonb_agg(to_jsonb(ce)), '[]') FROM tb_conta_eventos ce WHERE ce.id_evento=e.id_evento) contas FROM tb_evento_corridas e WHERE e.id_evento IN (36652,36657,36658,38203,38361,38571,39395,39399,39849,40716,41123,42366,42869,43036,43242,43664,43669,43923,44158,44270,44524,44821,44832,44834,44998,45000,45279,45305,45365,45587,45663,45670,45831,45842,45869,45894,45899,46047,46059,46060,46064,46210,46218,46253,46516,46568,46607,46873,46883,46928,46947,46959,47146,47202,47406,47431,47443,47453,47657,47669,47672,47686,47687,47688,47704,47780,47877,47888,47911,47957,47971,48085,48240,48419,48425,48458,48511,48714,48717,48730,48949,48978,48990,49002))e),'event_columns',(SELECT jsonb_agg(jsonb_build_object('name',column_name,'type',data_type,'nullable',is_nullable,'default',column_default)) FROM information_schema.columns WHERE table_name='tb_conta_eventos'))::text payload